{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect Meeting Notes or Transcript",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Meeting notes", "Meeting transcript (if available)"],
        "outputs": ["Collected raw meeting content"]
      },
      {
        "id": "A2",
        "name": "Draft Meeting Summary",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Collected raw meeting content"],
        "outputs": ["Draft meeting summary including decisions, action items, and owners"]
      },
      {
        "id": "A3",
        "name": "Identify Email Recipients",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Meeting context", "Relevant stakeholder information"],
        "outputs": ["Recipient list"]
      },
      {
        "id": "A4",
        "name": "Compose Summary Email",
        "actor": "Minute Taker",
        "system": "Unknown",
        "inputs": ["Draft meeting summary", "Recipient list"],
        "outputs": ["Composed summary email with required sections: decisions, action items, owners"]
      },
      {
        "id": "A5",
        "name": "Send Summary Email",
        "actor": "Minute Taker",
        "system": "Email system",
        "inputs": ["Composed summary email", "Recipient list"],
        "outputs": ["Sent email confirmation"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is the meeting transcript or sufficient notes available?",
        "branches": [
          "Yes: proceed to draft summary (A2)",
          "No: exception handling — missing transcript"
        ]
      },
      {
        "id": "D2",
        "condition": "Is the recipient list complete and all addresses valid?",
        "branches": [
          "Yes: proceed to compose email (A4)",
          "No: exception handling — incomplete or invalid recipient list"
        ]
      },
      {
        "id": "D3",
        "condition": "Does the summary contain confidential content?",
        "branches": [
          "No: proceed to send email (A5)",
          "Yes: exception handling — confidential content flagged"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "name": "Missing Transcript or Notes",
        "description": "The minute taker cannot draft the summary because no transcript or adequate notes are available.",
        "trigger": "D1 — insufficient source material",
        "resolution": "Unknown — no defined fallback process"
      },
      {
        "id": "E2",
        "name": "Unclear Decision Owner",
        "description": "One or more action items or decisions in the summary cannot be assigned to a clear owner.",
        "trigger": "During drafting (A2)",
        "resolution": "Unknown — no defined escalation or clarification process"
      },
      {
        "id": "E3",
        "name": "Incomplete or Invalid Recipient List",
        "description": "The recipient list is missing relevant people or contains invalid email addresses.",
        "trigger": "D2 — recipient validation",
        "resolution": "Unknown — no defined correction process"
      },
      {
        "id": "E4",
        "name": "Confidential Content Included",
        "description": "The summary draft contains content that should not be distributed to all recipients.",
        "trigger": "D3 — content review",
        "resolution": "Unknown — no defined redaction or access-control process"
      },
      {
        "id": "E5",
        "name": "Email System Unavailable",
        "description": "The email system is unavailable when the minute taker attempts to send the summary.",
        "trigger": "A5 — send failure",
        "resolution": "Unknown — no defined retry or alternative delivery process"
      }
    ],
    "dependencies": [
      {
        "from": "A1",
        "to": "D1",
        "type": "control_flow"
      },
      {
        "from": "D1",
        "to": "A2",
        "type": "control_flow"
      },
      {
        "from": "A2",
        "to": "A3",
        "type": "control_flow"
      },
      {
        "from": "A3",
        "to": "D2",
        "type": "control_flow"
      },
      {
        "from": "D2",
        "to": "A4",
        "type": "control_flow"
      },
      {
        "from": "A4",
        "to": "D3",
        "type": "control_flow"
      },
      {
        "from": "D3",
        "to": "A5",
        "type": "control_flow"
      }
    ]
  },
  "automation_opportunities": [
    {
      "target": "A1 — Collect Meeting Notes or Transcript",
      "rationale": "If meetings are conducted on a platform that produces automatic transcripts, collection could be triggered automatically at meeting end, eliminating manual initiation.",
      "required_data": ["Meeting platform integration", "Transcript availability flag", "Meeting end event"],
      "constraints": ["Meeting platform must support transcript export", "Privacy and consent rules for recording must be satisfied"],
      "confidence": "medium"
    },
    {
      "target": "A2 — Draft Meeting Summary",
      "rationale": "AI-based summarization tools can generate structured summaries from transcripts or notes, pre-populating decisions, action items, and owners sections.",
      "required_data": ["Raw transcript or notes", "Summary template structure (decisions, action items, owners)"],
      "constraints": ["AI output must be reviewed for accuracy", "Confidential content detection must be applied before distribution", "Quality of output depends on transcript clarity"],
      "confidence": "medium"
    },
    {
      "target": "A3 — Identify Email Recipients",
      "rationale": "If meeting invites are stored in a calendar system, the recipient list could be automatically derived from attendees, reducing manual effort and risk of omissions.",
      "required_data": ["Calendar system integration", "Meeting invite attendee list"],
      "constraints": ["Method of recipient selection is currently undefined — requires policy decision", "Not all invitees may be appropriate recipients"],
      "confidence": "low"
    },
    {
      "target": "A4 — Compose Summary Email",
      "rationale": "Email composition could be automated using a standard template pre-filled with structured summary content, ensuring required sections are always present.",
      "required_data": ["Approved summary template", "Structured summary data (decisions, action items, owners)", "Recipient list"],
      "constraints": ["Template must be agreed upon and maintained", "Customisation per meeting type may be needed"],
      "confidence": "high"
    },
    {
      "target": "D3 — Confidential Content Check",
      "rationale": "Automated content classification could flag potentially confidential terms or topics before sending, reducing the risk of unintended disclosure.",
      "required_data": ["Confidentiality classification rules or keyword lists", "Summary text"],
      "constraints": ["Classification accuracy must be validated", "Rules must be maintained as policies evolve"],
      "confidence": "medium"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "The method for selecting email recipients is undefined. It is unknown whether recipients are drawn from the meeting invite, a standing distribution list, or chosen ad hoc each time."
    },
    {
      "id": "G2",
      "description": "No system or tooling is specified for any step — it is unknown whether a specific email client, document editor, or meeting platform is used."
    },
    {
      "id": "G3",
      "description": "No approval or review step is defined before sending. It is unclear whether this is a deliberate policy choice or an unaddressed risk."
    },
    {
      "id": "G4",
      "description": "Deadlines for action items are implied as part of the summary but not explicitly required. The policy on whether deadlines must be captured is unconfirmed."
    },
    {
      "id": "G5",
      "description": "Resolution procedures for all identified exceptions (missing transcript, unclear owner, invalid recipients, confidential content, email system failure) are undefined."
    },
    {
      "id": "G6",
      "description": "It is unknown whether there is a required timeframe within which the summary must be sent after the meeting concludes."
    },
    {
      "id": "G7",
      "description": "It is unknown whether sent summaries are archived, and if so, in which system or for how long."
    },
    {
      "id": "G8",
      "description": "It is unclear how the process handles meetings with no transcript and no adequate notes — whether the summary is skipped, delayed, or reconstructed from memory."
    }
  ]
}
